1	/**
2	 * JARVIS-KP-01 · I2 — Pure Constitutional Epistemic Join Evaluator · closed types.
3	 *
4	 * Controlling law: NO SEMANTIC JOIN WITHOUT A WARRANT.
5	 *
6	 * Canonical operation grammar (ACT 11 §2.5, unchanged by ACT 11A §3):
7	 *   REFERENCE -> REPORT/MOVE -> COMPARE/JUXTAPOSE -> HYPOTHESIZE
8	 *     -> WARRANTED JOIN -> PROMOTE/DISCHARGE
9	 *
10	 * These vocabularies are CLOSED on purpose. A join whose authorship, jurisdiction,
11	 * warrant class, composition method, or relation semantics cannot be named inside
12	 * this file is not thereby admissible by default: it is unnameable, and an
13	 * unnameable relation fails closed for standing elevation (I1 §10).
14	 *
15	 * This module is constitutional computation only. It holds no persistence,
16	 * projection, prompt, memory, graph, or representation authority. The seams named
17	 * in I1 §2.1 as later work — a persistence adapter and a read-model projection —
18	 * are deliberately ABSENT from this candidate rather than present and disabled.
19	 */
20	
21	// ---------------------------------------------------------------------------
22	// Identity
23	// ---------------------------------------------------------------------------
24	
25	export type JoinId = string;
26	export type ComponentId = string;
27	export type WarrantId = string;
28	export type EndpointId = string;
29	export type ActId = string;
30	export type MemberScope = string;
31	
32	// ---------------------------------------------------------------------------
33	// Standing (ACT 11 §3 · I1 §3.5)
34	// ---------------------------------------------------------------------------
35	
36	/**
37	 * The closed standing vocabulary. NONE..PROMOTED form an elevation ladder;
38	 * DISCHARGED and SUPERSEDED are terminal dispositions for the proposition as
39	 * asserted, never rungs above PROMOTED.
40	 */
41	export type RelationStanding =
42	  | 'NONE_UNASSERTED'
43	  | 'CANDIDATE_UNESTABLISHED'
44	  | 'PROVISIONAL'
45	  | 'WARRANTED'
46	  | 'PROMOTED'
47	  | 'DISCHARGED'
48	  | 'SUPERSEDED';
49	
50	/** Rank on the elevation ladder. Terminal dispositions have no rank. */
51	export const ELEVATION_LADDER: readonly RelationStanding[] = [
52	  'NONE_UNASSERTED',
53	  'CANDIDATE_UNESTABLISHED',
54	  'PROVISIONAL',
55	  'WARRANTED',
56	  'PROMOTED',
57	] as const;
58	
59	export const TERMINAL_STANDINGS: readonly RelationStanding[] = ['DISCHARGED', 'SUPERSEDED'] as const;
60	
61	// ---------------------------------------------------------------------------
62	// Operation stage (ACT 11 §2.5)
63	// ---------------------------------------------------------------------------
64	
65	export type EpistemicOperation =
66	  | 'REFERENCE'
67	  | 'REPORT_MOVE'
68	  | 'COMPARE_JUXTAPOSE'
69	  | 'HYPOTHESIZE'
70	  | 'WARRANTED_JOIN'
71	  | 'PROMOTE'
72	  | 'DISCHARGE';
73	
74	// ---------------------------------------------------------------------------
75	// Authorship (ACT 11 §2.3)
76	// ---------------------------------------------------------------------------
77	
78	export type JoinAuthorClass =
79	  | 'SOURCE_AUTHORED'
80	  | 'MEMBER_AUTHORED'
81	  | 'MEMBER_CONFIRMED'
82	  | 'PRACTITIONER_AUTHORED'
83	  | 'JARVIS_AUTHORED'
84	  | 'MAIA_PROPOSED'
85	  | 'OTHER_DECLARED_AUTHORITY';
86	
87	/** Authorities that may hold an epistemic role. The same human may occupy several. */
88	export type AuthorityRole = 'member' | 'practitioner' | 'maia' | 'jarvis' | 'source' | 'other_declared';
89	
90	export interface Authorship {
91	  readonly authorClass: JoinAuthorClass;
92	  /** The role actually exercised for THIS act, not every role the actor could hold. */
93	  readonly roleExercised: AuthorityRole;
94	  /** Stable identity of the author within its role. */
95	  readonly authorRef: string;
96	}
97	
98	// ---------------------------------------------------------------------------
99	// Jurisdiction (ACT 11 §7)
100	// ---------------------------------------------------------------------------
101	
102	export type Jurisdiction =
103	  | 'member_lived_account'
104	  | 'member_personal_meaning'
105	  | 'practitioner_interpretation'
106	  | 'scientific_evidence'
107	  | 'named_philosophical_system'
108	  | 'product_design_analysis'
109	  | 'jarvis_research_analysis'
110	  | 'maia_conversational_inquiry'
111	  | 'historical_record'
112	  | 'metaphysical'
113	  | 'clinical_diagnostic';
114	
115	// ---------------------------------------------------------------------------
116	// Relation semantics — the epistemic force actually claimed (ACT 11 §2.2, §4)
117	// ---------------------------------------------------------------------------
118	
119	export type RelationSemantics =
120	  | 'co_presence'
121	  | 'comparison'
122	  | 'association'
123	  | 'correlation'
124	  | 'conflict'
125	  | 'explanatory_fit'
126	  | 'symbolic_correspondence'
127	  | 'temporal_sequence'
128	  | 'causation'
129	  | 'direction'
130	  | 'equivalence'
131	  | 'identity'
132	  | 'permanence'
133	  | 'psychological_meaning'
134	  | 'universality'
135	  | 'outcome';
136	
137	// ---------------------------------------------------------------------------
138	// Reference vs reliance (ACT 11 §12 · INV-10)
139	// ---------------------------------------------------------------------------
140	
141	/**
142	 * REFERENCE: material is named, displayed, cited, or used illustratively.
143	 * RELIANCE: a downstream proposition materially depends upon it.
144	 *
145	 * The distinction is declared, never inferred from the fact of mention.
146	 */
147	export type DependenceMode = 'reference' | 'reliance';
148	
149	export interface OperativeBoundary {
150	  readonly boundaryId: string;
151	  readonly statement: string;
152	  /** True while the boundary has not been discharged by genuinely new evidence. */
153	  readonly live: boolean;
154	}
155	
156	export interface Uncertainty {
157	  readonly statement: string;
158	  /**
159	   * Material conditions that block stronger standing (ACT 11 §6). Non-empty here
160	   * caps standing at PROVISIONAL; it never disappears into synthesis.
161	   */
162	  readonly blocksStrongerStanding: boolean;
163	}
164	
165	// ---------------------------------------------------------------------------
166	// Endpoints (ACT 11 §2.1 · INV-01)
167	// ---------------------------------------------------------------------------
168	
169	export interface Endpoint {
170	  readonly endpointId: EndpointId;
171	  readonly proposition: string;
172	  readonly authorship: Authorship;
173	  readonly provenanceRef: string;
174	  readonly standing: RelationStanding;
175	  readonly jurisdiction: Jurisdiction;
176	  readonly boundaries: readonly OperativeBoundary[];
177	  /** Whether the proposed relation RELIES on this endpoint or merely REFERENCES it. */
178	  readonly mode: DependenceMode;
179	}
180	
181	// ---------------------------------------------------------------------------
182	// Semantic components (ACT 11A §2.4 · A11A-INV-08)
183	// ---------------------------------------------------------------------------
184	
185	/**
186	 * The epistemic kind of a semantic component. This is what decides whether an
187	 * adopter's jurisdiction reaches the component — never the sentence it sits in.
188	 */
189	export type ComponentKind =
190	  | 'member_experience'
191	  | 'member_meaning'
192	  | 'member_value'
193	  | 'member_preference'
194	  | 'member_intention'
195	  | 'member_interpretation'
196	  | 'practitioner_interpretation'
197	  | 'external_motive'
198	  | 'external_intention'
199	  | 'external_causal_mechanism'
200	  | 'diagnostic'
201	  | 'scientific'
202	  | 'historical'
203	  | 'metaphysical'
204	  | 'universal_law';
205	
206	/**
207	 * Component kinds inside a member's own epistemic jurisdiction (ACT 11A §2.2).
208	 * Closed by law: adoption may elevate these and nothing else.
209	 */
210	export const MEMBER_AUTHORITATIVE_KINDS: readonly ComponentKind[] = [
211	  'member_experience',
212	  'member_meaning',
213	  'member_value',
214	  'member_preference',
215	  'member_intention',
216	  'member_interpretation',
217	] as const;
218	
219	export interface SemanticComponent {
220	  readonly componentId: ComponentId;
221	  readonly proposition: string;
222	  readonly kind: ComponentKind;
223	  readonly authorship: Authorship;
224	  readonly jurisdiction: Jurisdiction;
225	  /** The relation force this component itself asserts. */
226	  readonly claimedSemantics: readonly RelationSemantics[];
227	  /** Warrant relied upon for THIS component, where one is offered. */
228	  readonly warrantRef: WarrantId | null;
229	}
230	
231	// ---------------------------------------------------------------------------
232	// Warrants (ACT 11 §4 · ACT 11A §1.2)
233	// ---------------------------------------------------------------------------
234	
235	export type WarrantClass =
236	  | 'DIRECT_SOURCE_RELATION'
237	  | 'MEMBER_AUTHORED_RELATION'
238	  | 'MEMBER_CONFIRMATION'
239	  | 'PRACTITIONER_INTERPRETATION'
240	  | 'EMPIRICAL_RELATION_EVIDENCE'
241	  | 'FORMAL_ENTAILMENT'
242	  | 'THEORETICAL_ARGUMENT'
243	  | 'BOUNDARY_DISCHARGE_EVIDENCE'
244	  | 'OTHER_DECLARED_WARRANT';
245	
246	export type WarrantLiveness = 'live' | 'disputed' | 'weakened' | 'defeated';
247	
248	/**
249	 * How a support set is combined into a composite inference (ACT 11A §1.2).
250	 *
251	 * The last four are named so they can be REFUSED. Mere accumulation is not a
252	 * warrant: agreement, count, prestige, and restatement are not methods.
253	 */
254	export type CompositionMethod =
255	  | 'declared_formal_entailment'
256	  | 'convergent_independent_measurement'
257	  | 'explanatory_coherence'
258	  | 'mere_agreement'
259	  | 'source_count'
260	  | 'source_prestige'
261	  | 'restatement';
262	
263	export const NON_METHODS: readonly CompositionMethod[] = [
264	  'mere_agreement',
265	  'source_count',
266	  'source_prestige',
267	  'restatement',
268	] as const;
269	
270	/**
271	 * One relied-upon element of a composite support set. `sharedOriginRef` is how
272	 * pseudo-independence becomes inspectable: two entries carrying the same origin
273	 * are not independent, whatever the composition method claims.
274	 */
275	export interface SupportEntry {
276	  readonly supportId: string;
277	  readonly proposition: string;
278	  readonly provenanceRef: string;
279	  readonly mode: DependenceMode;
280	  readonly authorship: Authorship;
281	  readonly jurisdiction: Jurisdiction;
282	  readonly boundaries: readonly OperativeBoundary[];
283	  /** Shared upstream origin, where one exists. Null asserts nothing; it declares nothing known. */
284	  readonly sharedOriginRef: string | null;
285	  /** A nested composite warrant this entry stands on, if any. */
286	  readonly nestedWarrantRef: WarrantId | null;
287	}
288	
289	export interface DependenceAssumptions {
290	  /** Explicitly claimed independence among support entries. */
291	  readonly claimedIndependent: boolean;
292	  /** Declared, resolved account of shared origin / redundancy / correlation. */
293	  readonly resolved: boolean;
294	  readonly statement: string;
295	}
296	
297	/**
298	 * A warrant is evidence whose OWN standing licenses the relation being asserted.
299	 * A composite warrant is a separately authored inference over a support set; it
300	 * is never identical to that support set (A11A-INV-01).
301	 */
302	export interface Warrant {
303	  readonly warrantId: WarrantId;
304	  readonly warrantClass: WarrantClass;
305	  /** The relation or inferential claim this warrant supports. */
306	  readonly proposition: string;
307	  readonly authorship: Authorship;
308	  readonly provenanceRef: string;
309	  readonly jurisdiction: Jurisdiction;
310	  /** Cross-jurisdiction transfer must be declared, never inferred (ACT 11 §7). */
311	  readonly licensesTransferInto: readonly Jurisdiction[];
312	  readonly licensedRelationSemantics: readonly RelationSemantics[];
313	  readonly uncertainty: Uncertainty | null;
314	  readonly boundaries: readonly OperativeBoundary[];
315	  readonly liveness: WarrantLiveness;
316	  /** Highest standing this warrant can license, whatever an act requests. */
317	  readonly standingCeiling: RelationStanding;
318	  /** Present only for composite inference. A bare support set is not a composite. */
319	  readonly composite: {
320	    readonly supportSet: readonly SupportEntry[];
321	    readonly compositionMethod: CompositionMethod;
322	    readonly dependenceAssumptions: DependenceAssumptions;
323	  } | null;
324	}
325	
326	// ---------------------------------------------------------------------------
327	// Append-only acts (I1 §1.5, §3.5 · standing is DERIVED, never assigned)
328	// ---------------------------------------------------------------------------
329	
330	export type StandingActBasis =
331	  | 'initial_proposal'
332	  | 'warrant_admission'
333	  | 'new_evidence'
334	  | 'adoption'
335	  | 'conflict_emerged'
336	  | 'warrant_defeated'
337	  | 'superseded_by_later_proposition'
338	  | 'authority_withdrawal';
339	
340	/**
341	 * An append-only assertion that a standing was claimed for a join (or one of its
342	 * components) on a stated basis. The act is a request, not an authority: the
343	 * evaluator caps it by what the warrants license.
344	 */
345	export interface StandingAct {
346	  readonly actId: ActId;
347	  readonly joinId: JoinId;
348	  /** Null scopes the act to the whole join. */
349	  readonly componentId: ComponentId | null;
350	  readonly claimedStanding: RelationStanding;
351	  readonly basis: StandingActBasis;
352	  readonly warrantRef: WarrantId | null;
353	  readonly authorship: Authorship;
354	  readonly jurisdiction: Jurisdiction;
355	  /** Null marks the root act for this subject. One root per subject. */
356	  readonly supersedesActId: ActId | null;
357	}
358	
359	/**
360	 * An adoption act names the EXACT components adopted. Whole-sentence
361	 * confirmation cannot promote every component it contains (ACT 11A §2.4).
362	 */
363	export interface AdoptionAct {
364	  readonly actId: ActId;
365	  readonly joinId: JoinId;
366	  readonly adoptedComponentIds: readonly ComponentId[];
367	  readonly adopter: Authorship;
368	  readonly adopterJurisdiction: Jurisdiction;
369	  /** The proposition as put to the adopter, preserved for provenance (A11A-INV-10). */
370	  readonly propositionAsPut: string;
371	  /** Who originally proposed it. Never rewritten by adoption. */
372	  readonly originalProposer: Authorship;
373	}
374	
375	// ---------------------------------------------------------------------------
376	// The join envelope (ACT 11 §2 · I1 §3)
377	// ---------------------------------------------------------------------------
378	
379	export interface JoinProvenance {
380	  /** Who or what introduced the RELATION — not where the endpoints came from. */
381	  readonly introducedBy: Authorship;
382	  readonly inquiryContext: string;
383	  /** Endpoint/support material actually relied upon for the relation. */
384	  readonly reliedUponRefs: readonly string[];
385	  /** Material merely referenced. Kept separate by law (INV-10). */
386	  readonly referenceOnlyRefs: readonly string[];
387	  readonly transformationStep: string;
388	}
389	
390	export interface JoinEnvelope {
391	  readonly joinId: JoinId;
392	  readonly memberScope: MemberScope;
393	  readonly endpoints: readonly Endpoint[];
394	  /** The relation stated explicitly enough to inspect. Hidden verbs are still claims. */
395	  readonly relationProposition: string;
396	  readonly relationPredicate: string;
397	  readonly directional: boolean;
398	  readonly claimedSemantics: readonly RelationSemantics[];
399	  readonly operation: EpistemicOperation;
400	  readonly authorship: Authorship;
401	  readonly provenance: JoinProvenance;
402	  readonly jurisdiction: Jurisdiction;
403	  /** Warrants offered for the relation itself. An empty set is a lawful input. */
404	  readonly offeredWarrantRefs: readonly WarrantId[];
405	  readonly components: readonly SemanticComponent[];
406	  readonly boundaries: readonly OperativeBoundary[];
407	  readonly uncertainty: Uncertainty | null;
408	}
409	
410	// ---------------------------------------------------------------------------
411	// Evaluator input / output
412	// ---------------------------------------------------------------------------
413	
414	export interface EvaluationRequest {
415	  readonly envelope: JoinEnvelope;
416	  readonly warrants: readonly Warrant[];
417	  readonly standingActs: readonly StandingAct[];
418	  readonly adoptionActs: readonly AdoptionAct[];
419	  /** The standing whose admissibility is being asked about. */
420	  readonly requestedStanding: RelationStanding;
421	  /** The jurisdiction in which that standing is requested. */
422	  readonly requestedJurisdiction: Jurisdiction;
423	}
424	
425	/** Closed refusal / limitation vocabulary. Every refusal names its exact law. */
426	export type RefusalCode =
427	  | 'no_warrant_offered'
428	  | 'join_provenance_incomplete'
429	  | 'warrant_unknown'
430	  | 'warrant_not_live'
431	  | 'reference_offered_as_reliance'
432	  | 'reliance_not_declared'
433	  | 'support_set_offered_as_composite_warrant'
434	  | 'composite_method_is_mere_accumulation'
435	  | 'composite_missing_dependence_resolution'
436	  | 'composite_pseudo_independence'
437	  | 'composite_circular_support'
438	  | 'composite_nested_standing_ceiling'
439	  | 'composite_method_does_not_license_semantics'
440	  | 'jurisdiction_mismatch'
441	  | 'cross_jurisdiction_transfer_undeclared'
442	  | 'semantics_not_licensed'
443	  | 'boundary_loss'
444	  | 'uncertainty_blocks_elevation'
445	  | 'standing_exceeds_warrant_ceiling'
446	  | 'endpoint_evidence_offered_as_relation_evidence'
447	  | 'authorship_composition_attempted'
448	  | 'adoption_outside_adopter_jurisdiction'
449	  | 'adoption_component_unknown'
450	  | 'adoption_provenance_lost'
451	  | 'operation_stage_below_requested_standing'
452	  | 'terminal_standing_not_re_elevable'
453	  | 'member_scope_violation';
454	
455	export interface Refusal {
456	  readonly code: RefusalCode;
457	  /** The law under pressure, cited by invariant id. */
458	  readonly invariant: string;
459	  readonly detail: string;
460	}
461	
462	export interface ComponentEvaluation {
463	  readonly componentId: ComponentId;
464	  readonly kind: ComponentKind;
465	  readonly jurisdiction: Jurisdiction;
466	  readonly requestedStanding: RelationStanding;
467	  readonly admittedStanding: RelationStanding;
468	  readonly warrantIdsReliedUpon: readonly WarrantId[];
469	  readonly adoptedBy: readonly AuthorityRole[];
470	  readonly refusals: readonly Refusal[];
471	  readonly lowerStandingRepresentationPermitted: boolean;
472	}
473	
474	export interface JoinEvaluation {
475	  readonly joinId: JoinId;
476	  readonly memberScope: MemberScope;
477	  readonly relationProposition: string;
478	  readonly requestedStanding: RelationStanding;
479	  /** The standing actually earned. Never above the warrant ceiling. */
480	  readonly admittedStanding: RelationStanding;
481	  readonly requestedJurisdiction: Jurisdiction;
482	  readonly admittedJurisdiction: Jurisdiction | null;
483	  readonly operation: EpistemicOperation;
484	  readonly warrantIdsReliedUpon: readonly WarrantId[];
485	  /** Whether every declared reliance was actually declared as reliance. */
486	  readonly relianceValid: boolean;
487	  readonly compositeWarrantRequired: boolean;
488	  readonly compositeWarrantSatisfied: boolean;
489	  readonly carriedBoundaries: readonly OperativeBoundary[];
490	  readonly carriedUncertainty: readonly Uncertainty[];
491	  readonly admissionReasons: readonly string[];
492	  readonly refusals: readonly Refusal[];
493	  readonly components: readonly ComponentEvaluation[];
494	  /** A refused promotion never erases meaning (INV-13). */
495	  readonly lowerStandingRepresentationPermitted: boolean;
496	  readonly permittedLowerStandingOperation: EpistemicOperation | null;
497	  /**
498	   * Structurally false in I2. Representation authority is closed: admission is
499	   * not representation, and no downstream surface is authorized by this result.
500	   */
501	  readonly downstreamRepresentationAuthorized: false;
502	  readonly representationAuthority: 'closed';
503	}
504	
505	/**
506	 * Structural malformation — the input is not a well-formed epistemic object.
507	 *
508	 * Distinct from a refusal: a refusal is a lawful verdict on a well-formed
509	 * object that did not earn standing. This is raised only when the input cannot
510	 * be evaluated at all without the evaluator inventing something (an unknown
511	 * reference, a duplicate act id, a branched standing chain).
512	 */
513	export class EpistemicJoinMalformed extends Error {
514	  readonly reason: string;
515	  readonly where: string;
516	
517	  constructor(reason: string, where: string) {
518	    super(`epistemic join input malformed: ${reason} (${where})`);
519	    this.name = 'EpistemicJoinMalformed';
520	    this.reason = reason;
521	    this.where = where;
522	  }
523	}
